contracts/DatasetRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title DatasetRegistry
 * @dev Enregistre les hash IPFS des datasets sur la blockchain
 * @author Lead Blockchain Engineer - DataMarketplace
 */
contract DatasetRegistry is Ownable, ReentrancyGuard {

    // ============================================================
    //  STRUCTURES
    // ============================================================

    struct Dataset {
        string  ipfsHash;        // Hash CID IPFS (ex: QmXxx...)
        address owner;           // Propriétaire du dataset
        uint256 price;           // Prix en tokens (en wei équivalent)
        uint256 registeredAt;    // Timestamp d'enregistrement
        uint256 usageCount;      // Nombre d'utilisations
        DataType dataType;       // Type de données
        bool    isActive;        // Disponible sur le marketplace
        string  metadata;        // JSON metadata (titre, description, tags)
        bytes32 contentHash;     // Hash SHA256 du contenu (anti-doublon)
    }

    enum DataType { IMAGE, TEXT, AUDIO, VIDEO, TABULAR, OTHER }

    // ============================================================
    //  STORAGE
    // ============================================================

    // datasetId => Dataset
    mapping(uint256 => Dataset) public datasets;

    // contentHash => datasetId (détection doublons)
    mapping(bytes32 => uint256) public contentHashToId;

    // owner => liste de ses datasetIds
    mapping(address => uint256[]) public ownerDatasets;

    // datasetId => acheteurs autorisés
    mapping(uint256 => mapping(address => bool)) public accessGranted;

    uint256 public nextDatasetId = 1;
    uint256 public platformFeePercent = 5; // 5% de frais plateforme

    // ============================================================
    //  EVENTS
    // ============================================================

    event DatasetRegistered(
        uint256 indexed datasetId,
        address indexed owner,
        string  ipfsHash,
        bytes32 contentHash,
        uint256 price,
        DataType dataType
    );

    event DatasetPurchased(
        uint256 indexed datasetId,
        address indexed buyer,
        address indexed owner,
        uint256 amount
    );

    event DatasetPriceUpdated(
        uint256 indexed datasetId,
        uint256 oldPrice,
        uint256 newPrice
    );

    event DatasetDeactivated(uint256 indexed datasetId);

    // ============================================================
    //  MODIFIERS
    // ============================================================

    modifier onlyDatasetOwner(uint256 _datasetId) {
        require(datasets[_datasetId].owner == msg.sender, "Not dataset owner");
        _;
    }

    modifier datasetExists(uint256 _datasetId) {
        require(_datasetId > 0 && _datasetId < nextDatasetId, "Dataset not found");
        _;
    }

    modifier datasetActive(uint256 _datasetId) {
        require(datasets[_datasetId].isActive, "Dataset not active");
        _;
    }

    // ============================================================
    //  CONSTRUCTOR
    // ============================================================

    constructor() Ownable(msg.sender) {}

    // ============================================================
    //  CORE FUNCTIONS
    // ============================================================

    /**
     * @dev Enregistre un nouveau dataset
     * @param _ipfsHash  CID IPFS du fichier uploadé
     * @param _contentHash Hash SHA256 du contenu (calculé off-chain)
     * @param _price     Prix en wei
     * @param _dataType  Type de données
     * @param _metadata  JSON string avec titre, description, tags
     */
    function registerDataset(
        string  calldata _ipfsHash,
        bytes32          _contentHash,
        uint256          _price,
        DataType         _dataType,
        string  calldata _metadata
    ) external nonReentrant returns (uint256 datasetId) {

        require(bytes(_ipfsHash).length > 0,    "Empty IPFS hash");
        require(_contentHash != bytes32(0),      "Empty content hash");
        require(contentHashToId[_contentHash] == 0, "Duplicate content detected");

        datasetId = nextDatasetId++;

        datasets[datasetId] = Dataset({
            ipfsHash:    _ipfsHash,
            owner:       msg.sender,
            price:       _price,
            registeredAt: block.timestamp,
            usageCount:  0,
            dataType:    _dataType,
            isActive:    true,
            metadata:    _metadata,
            contentHash: _contentHash
        });

        contentHashToId[_contentHash] = datasetId;
        ownerDatasets[msg.sender].push(datasetId);

        emit DatasetRegistered(
            datasetId,
            msg.sender,
            _ipfsHash,
            _contentHash,
            _price,
            _dataType
        );
    }

    /**
     * @dev Achète l'accès à un dataset (paiement en ETH natif)
     */
    function purchaseAccess(uint256 _datasetId)
        external
        payable
        nonReentrant
        datasetExists(_datasetId)
        datasetActive(_datasetId)
    {
        Dataset storage dataset = datasets[_datasetId];

        require(!accessGranted[_datasetId][msg.sender], "Already purchased");
        require(msg.sender != dataset.owner, "Owner already has access");
        require(msg.value >= dataset.price, "Insufficient payment");

        // Calcul des frais plateforme
        uint256 fee          = (msg.value * platformFeePercent) / 100;
        uint256 ownerAmount  = msg.value - fee;

        // Transfert au propriétaire
        (bool success, ) = payable(dataset.owner).call{value: ownerAmount}("");
        require(success, "Transfer to owner failed");

        // Les frais restent dans le contrat (pour la plateforme)

        accessGranted[_datasetId][msg.sender] = true;
        dataset.usageCount++;

        emit DatasetPurchased(_datasetId, msg.sender, dataset.owner, msg.value);
    }

    /**
     * @dev Vérifie si un dataset existe déjà (anti-doublon)
     */
    function checkDuplicate(bytes32 _contentHash) external view returns (bool exists, uint256 datasetId) {
        datasetId = contentHashToId[_contentHash];
        exists    = datasetId != 0;
    }

    /**
     * @dev Retourne tous les datasets d'un owner
     */
    function getOwnerDatasets(address _owner) external view returns (uint256[] memory) {
        return ownerDatasets[_owner];
    }

    /**
     * @dev Met à jour le prix d'un dataset
     */
    function updatePrice(uint256 _datasetId, uint256 _newPrice)
        external
        datasetExists(_datasetId)
        onlyDatasetOwner(_datasetId)
    {
        uint256 oldPrice = datasets[_datasetId].price;
        datasets[_datasetId].price = _newPrice;
        emit DatasetPriceUpdated(_datasetId, oldPrice, _newPrice);
    }

    /**
     * @dev Désactive un dataset du marketplace
     */
    function deactivateDataset(uint256 _datasetId)
        external
        datasetExists(_datasetId)
        onlyDatasetOwner(_datasetId)
    {
        datasets[_datasetId].isActive = false;
        emit DatasetDeactivated(_datasetId);
    }

    /**
     * @dev Withdrawal des frais plateforme (owner uniquement)
     */
    function withdrawFees(address payable _to) external onlyOwner {
        uint256 balance = address(this).balance;
        require(balance > 0, "No fees to withdraw");
        (bool success, ) = _to.call{value: balance}("");
        require(success, "Withdrawal failed");
    }

    /**
     * @dev Mise à jour des frais plateforme
     */
    function setPlatformFee(uint256 _feePercent) external onlyOwner {
        require(_feePercent <= 20, "Fee too high");
        platformFeePercent = _feePercent;
    }
}

contracts/DataToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/ERC20Burnable.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";

/**
 * @title DataToken (DTK)
 * @dev Token utilitaire ERC-20 pour récompenser les contributeurs
 */
contract DataToken is ERC20, ERC20Burnable, AccessControl {

    bytes32 public constant MINTER_ROLE   = keccak256("MINTER_ROLE");
    bytes32 public constant BURNER_ROLE   = keccak256("BURNER_ROLE");

    uint256 public constant MAX_SUPPLY    = 1_000_000_000 * 1e18; // 1 milliard DTK
    uint256 public totalMinted;

    event TokensMinted(address indexed to, uint256 amount, string reason);
    event TokensBurned(address indexed from, uint256 amount);

    constructor(address _admin) ERC20("DataToken", "DTK") {
        _grantRole(DEFAULT_ADMIN_ROLE, _admin);
        _grantRole(MINTER_ROLE, _admin);

        // Mint initial supply pour la plateforme (10%)
        uint256 initialSupply = MAX_SUPPLY / 10;
        _mint(_admin, initialSupply);
        totalMinted += initialSupply;
    }

    /**
     * @dev Mint des tokens pour récompenser un contributeur
     * @param _to      Adresse du bénéficiaire
     * @param _amount  Montant en wei (18 décimales)
     * @param _reason  Raison du mint (ex: "dataset_upload", "task_completed")
     */
    function mintReward(address _to, uint256 _amount, string calldata _reason)
        external
        onlyRole(MINTER_ROLE)
    {
        require(totalMinted + _amount <= MAX_SUPPLY, "Max supply exceeded");
        require(_to != address(0), "Invalid address");

        _mint(_to, _amount);
        totalMinted += _amount;

        emit TokensMinted(_to, _amount, _reason);
    }

    /**
     * @dev Burn des tokens (pour les achats sur le marketplace)
     */
    function burnFrom(address _from, uint256 _amount)
        public
        override
        onlyRole(BURNER_ROLE)
    {
        _burn(_from, _amount);
        emit TokensBurned(_from, _amount);
    }

    /**
     * @dev Retourne la supply restante mintable
     */
    function remainingSupply() external view returns (uint256) {
        return MAX_SUPPLY - totalMinted;
    }
}

contracts/RewardDistributor.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "./DataToken.sol";

/**
 * @title RewardDistributor
 * @dev Distribue automatiquement les tokens selon les actions des utilisateurs
 *
 * Système de récompenses :
 * - Upload dataset        → 50 DTK de base + bonus qualité
 * - Tâche complétée       → 100 DTK
 * - Dataset utilisé       → 10 DTK par utilisation (passif)
 * - Parrainage            →  20 DTK
 */
contract RewardDistributor is Ownable, ReentrancyGuard {

    DataToken public immutable token;

    // ============================================================
    //  REWARD AMOUNTS (en DTK avec 18 décimales)
    // ============================================================

    uint256 public rewardUpload       = 50  * 1e18;
    uint256 public rewardTaskComplete = 100 * 1e18;
    uint256 public rewardDatasetUsed  = 10  * 1e18;
    uint256 public rewardReferral     = 20  * 1e18;

    // ============================================================
    //  USER SCORES & STATS
    // ============================================================

    struct UserStats {
        uint256 totalEarned;     // Total de tokens gagnés (historique)
        uint256 datasetsUploaded;
        uint256 tasksCompleted;
        uint256 datasetsUsed;    // Nombre de fois que ses données ont été utilisées
        uint256 level;           // Niveau calculé automatiquement
        bool    registered;
    }

    mapping(address => UserStats) public userStats;
    mapping(address => address)   public referrals;      // user => referrer

    // Prévenir les doubles récompenses pour un même dataset
    mapping(bytes32 => bool) public rewardProcessed;

    address public registryContract; // DatasetRegistry autorisé à déclencher des rewards

    // ============================================================
    //  EVENTS
    // ============================================================

    event RewardIssued(
        address indexed user,
        uint256 amount,
        string  rewardType,
        uint256 newTotalEarned
    );

    event UserLevelUp(address indexed user, uint256 oldLevel, uint256 newLevel);
    event UserRegistered(address indexed user, address indexed referrer);

    // ============================================================
    //  MODIFIERS
    // ============================================================

    modifier onlyRegistry() {
        require(msg.sender == registryContract || msg.sender == owner(), "Not authorized");
        _;
    }

    // ============================================================
    //  CONSTRUCTOR
    // ============================================================

    constructor(address _tokenAddress) Ownable(msg.sender) {
        token = DataToken(_tokenAddress);
    }

    // ============================================================
    //  REGISTRATION
    // ============================================================

    /**
     * @dev Inscription d'un utilisateur avec parrainage optionnel
     */
    function registerUser(address _referrer) external {
        require(!userStats[msg.sender].registered, "Already registered");

        userStats[msg.sender].registered = true;
        userStats[msg.sender].level      = 1;

        emit UserRegistered(msg.sender, _referrer);

        // Bonus parrainage
        if (_referrer != address(0) && _referrer != msg.sender && userStats[_referrer].registered) {
            referrals[msg.sender] = _referrer;
            _issueReward(_referrer, rewardReferral, "referral");
        }
    }

    // ============================================================
    //  REWARD FUNCTIONS
    // ============================================================

    /**
     * @dev Récompense pour un upload de dataset
     * @param _user      Uploadeur
     * @param _datasetId ID du dataset
     * @param _qualityScore Score de qualité 0-100 (donné par l'Agent VLM)
     */
    function rewardDatasetUpload(
        address _user,
        uint256 _datasetId,
        uint8   _qualityScore
    ) external onlyRegistry nonReentrant {
        bytes32 key = keccak256(abi.encodePacked("upload", _datasetId));
        require(!rewardProcessed[key], "Already rewarded");

        rewardProcessed[key] = true;

        // Bonus qualité : jusqu'à +100% si qualityScore = 100
        uint256 bonus  = (rewardUpload * _qualityScore) / 100;
        uint256 amount = rewardUpload + bonus;

        userStats[_user].datasetsUploaded++;
        _issueReward(_user, amount, "dataset_upload");
    }

    /**
     * @dev Récompense passive quand un dataset est utilisé/acheté
     */
    function rewardDatasetUsage(address _owner, uint256 _datasetId)
        external
        onlyRegistry
        nonReentrant
    {
        // Pas de limite ici, chaque utilisation génère une récompense
        userStats[_owner].datasetsUsed++;
        _issueReward(_owner, rewardDatasetUsed, "dataset_used");

        // Clé unique par usage pour tracking
        emit RewardIssued(_owner, rewardDatasetUsed, "dataset_used", userStats[_owner].totalEarned);
    }

    /**
     * @dev Récompense pour complétion d'une tâche assignée par l'Agent Task Generator
     * @param _user      Utilisateur
     * @param _taskId    ID de la tâche
     * @param _bonusMultiplier Multiplicateur 100 = x1, 200 = x2 (selon difficulté)
     */
    function rewardTaskCompletion(
        address _user,
        uint256 _taskId,
        uint16  _bonusMultiplier
    ) external onlyOwner nonReentrant {
        bytes32 key = keccak256(abi.encodePacked("task", _taskId, _user));
        require(!rewardProcessed[key], "Task already rewarded");

        rewardProcessed[key] = true;

        uint256 amount = (rewardTaskComplete * _bonusMultiplier) / 100;
        userStats[_user].tasksCompleted++;
        _issueReward(_user, amount, "task_completed");
    }

    // ============================================================
    //  INTERNAL
    // ============================================================

    function _issueReward(address _user, uint256 _amount, string memory _type) internal {
        userStats[_user].totalEarned += _amount;
        token.mintReward(_user, _amount, _type);

        uint256 oldLevel = userStats[_user].level;
        uint256 newLevel = _calculateLevel(userStats[_user].totalEarned);

        if (newLevel > oldLevel) {
            userStats[_user].level = newLevel;
            emit UserLevelUp(_user, oldLevel, newLevel);
        }

        emit RewardIssued(_user, _amount, _type, userStats[_user].totalEarned);
    }

    /**
     * @dev Calcule le niveau utilisateur basé sur ses gains totaux
     * Niveau 1: 0 - 500 DTK
     * Niveau 2: 500 - 2000 DTK
     * Niveau 3: 2000 - 10000 DTK
     * Niveau 4: 10000+ DTK
     */
    function _calculateLevel(uint256 _totalEarned) internal pure returns (uint256) {
        uint256 earned = _totalEarned / 1e18; // Convertir en DTK entiers
        if (earned >= 10_000) return 4;
        if (earned >= 2_000)  return 3;
        if (earned >= 500)    return 2;
        return 1;
    }

    // ============================================================
    //  CONFIG
    // ============================================================

    function setRegistryContract(address _registry) external onlyOwner {
        registryContract = _registry;
    }

    function updateRewardAmounts(
        uint256 _upload,
        uint256 _task,
        uint256 _usage,
        uint256 _referral
    ) external onlyOwner {
        rewardUpload       = _upload;
        rewardTaskComplete = _task;
        rewardDatasetUsed  = _usage;
        rewardReferral     = _referral;
    }

    /**
     * @dev Retourne les stats complètes d'un utilisateur
     */
    function getUserProfile(address _user) external view returns (
        uint256 totalEarned,
        uint256 datasetsUploaded,
        uint256 tasksCompleted,
        uint256 datasetsUsed,
        uint256 level,
        uint256 tokenBalance
    ) {
        UserStats memory stats = userStats[_user];
        return (
            stats.totalEarned,
            stats.datasetsUploaded,
            stats.tasksCompleted,
            stats.datasetsUsed,
            stats.level,
            token.balanceOf(_user)
        );
    }
}

